import json
from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import DevicegwURI


class DamoclesV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_node_power_state(self, node_id, timeout=60):
        uri = DevicegwURI().devicegw_powerstate_uri + "/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def set_node_power_state(self, node_id, power_state, timeout=60):
        uri = DevicegwURI().devicegw_power_uri + "/" + node_id
        body = {"op": "{}".format(power_state.lower())}
        return self.api_client.send_post_request(uri=uri, data=json.dumps(body), timeout=timeout)
